import{_ as n,c as t,o as s,ag as i}from"./chunks/framework.Sr95JMjc.js";const d=JSON.parse('{"title":"Spring Boot Environment Variables","description":"","frontmatter":{"title":"Spring Boot Environment Variables","date":"2025-01-19T10:00+09:00","tags":["Spring Boot","Environment","Properties","Dotenv"]},"headers":[],"relativePath":"posts/spring-boot-env.md","filePath":"posts/spring-boot-env.md","lastUpdated":1777592848000}'),a={name:"posts/spring-boot-env.md"};function r(o,e,p,l,h,g){return s(),t("div",null,[...e[0]||(e[0]=[i(`<p>회사에서 프로젝트 리파지토리 내 존재하는 환경별 속성 파일을 제거하고 환경 변수를 이용하기로 요구되었습니다. 개발 과정에서는 인텔리제이의 <a href="https://plugins.jetbrains.com/plugin/7861-envfile" target="_blank" rel="noreferrer">EnvFile 플러그인</a>을 이용해 로컬에 만든 .env 파일을 환경 변수로 적용할 수 있었지만 단위 테스트 코드를 실행할 때에는 매번 실행 환경을 수정하는게 불편해서 단위 테스트 시 환경 변수를 적용하기 위한 방법에 대해서 찾아봤습니다.</p><h4 id="spring-dotenv" tabindex="-1">spring-dotenv <a class="header-anchor" href="#spring-dotenv" aria-label="Permalink to &quot;spring-dotenv&quot;">​</a></h4><p><a href="https://github.com/paulschwarz/spring-dotenv" target="_blank" rel="noreferrer">spring-dotenv</a>를 사용하면 애플리케이션 속성 파일에 환경 변수 형태로 적용할 수 있지만 <u>애플리케이션 속성 파일에 따라 자동으로 적용되지는 않는다</u>는 단점이 있습니다. 예를 들어, 스프링 부트 애플리케이션의 배너를 제외하기 위해서 SPRING_MAIN_BANNERMODE이 dotenv 파일에 정의되어 있어도 애플리케이션 속성 파일에 <u>SPRING_MAIN_BANNERMODE를 사용하도록 별도로 지정하지 않으면</u> 사용할 수 없습니다.</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># dev.env</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SPRING_MAIN_BANNERMODE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=off</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># application.properties</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spring.main.banner-mode</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=\${SPRING_MAIN_BANNERMODE:console}</span></span></code></pre></div><blockquote><p>기본적으로 OS 환경 변수는 정해진 패턴에 따라 스프링 부트에서 지원하는 <a href="https://docs.spring.io/spring-boot/reference/features/external-config.html#features.external-config.typesafe-configuration-properties.relaxed-binding.environment-variables" target="_blank" rel="noreferrer">Externalized Configuration</a>에 따라 애플리케이션 속성으로 반영됩니다. 따라서, <a href="https://docs.docker.com/compose/how-tos/environment-variables/set-environment-variables/#use-the-env_file-attribute" target="_blank" rel="noreferrer">도커 컴포즈</a> 또는 <a href="https://docs.aws.amazon.com/AmazonECS/latest/developerguide/use-environment-file.html" target="_blank" rel="noreferrer">Amazon ECS</a>에서는 dotenv 파일로 환경변수를 지정할 수 있죠.</p></blockquote><h4 id="environment를-커스터마이징할-수-있는-여러가지-방법" tabindex="-1">Environment를 커스터마이징할 수 있는 여러가지 방법 <a class="header-anchor" href="#environment를-커스터마이징할-수-있는-여러가지-방법" aria-label="Permalink to &quot;Environment를 커스터마이징할 수 있는 여러가지 방법&quot;">​</a></h4><ul><li><a href="https://www.baeldung.com/spring-boot-environmentpostprocessor" target="_blank" rel="noreferrer">EnvironmentPostProcessor</a></li><li>ContextConfiguration + ApplicationContextListener + <a href="https://docs.spring.io/spring-boot/reference/testing/test-utilities.html#testing.utilities.test-property-values" target="_blank" rel="noreferrer">TestPropertyValues</a></li><li><a href="https://docs.spring.io/spring-framework/reference/testing/annotations/integration-spring/annotation-testpropertysource.html" target="_blank" rel="noreferrer">@TestPropertySource</a></li></ul><p>단위 테스트 코드를 실행하는 경우 위와 같은 방법으로 Environment를 커스터마이징할 수 있는데요. 이를 통해서 일부 애플리케이션 속성을 변경할 수 있지만 .env 파일을 지정할 순 없습니다. 앞서 spring-dotenv를 사용하려면 애플리케이션 속성 파일에 재정의가 필요하고 단위 테스트를 개별로 수행할 때마다 실행 환경에서 EnvFile 플러그인을 활성화하기에는 너무나도 불편합니다.</p><h4 id="스프링-배너-출력은-environment로-동작하지-않는다" tabindex="-1">스프링 배너 출력은 Environment로 동작하지 않는다? <a class="header-anchor" href="#스프링-배너-출력은-environment로-동작하지-않는다" aria-label="Permalink to &quot;스프링 배너 출력은 Environment로 동작하지 않는다?&quot;">​</a></h4><p>이 글을 작성하기 위해서 테스트를 해보던 중 스프링 배너 출력에 대한 속성값은 TestPropertySource와 DotenvPropertySource 모두 Environment에 반영되어 테스트는 통과했으나 실제 스프링 배너 출력은 변경되기 이전의 값으로 동작했고 TestPropertyValues 또는 EnvironmentPostProcessor 에서 <u>시스템 프로퍼티로 등록해야만</u> 제대로 반영되어 출력되지 않는 것을 확인할 수 있었습니다.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ActiveProfiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;test&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SpringBootTest</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ApplicationTests</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {}</span></span></code></pre></div><p>프로덕션 배포가 아닌 단위 테스트 시에는 .env 파일을 사용하지 않고 별도의 애플리케이션 속성 파일(application-test.yml)을 두고 <a href="https://docs.spring.io/spring-framework/reference/testing/annotations/integration-spring/annotation-activeprofiles.html" target="_blank" rel="noreferrer">@ActiveProfiles</a>를 활용하는 것이 그나마 제일 나은 선택지일 것 같습니다. 스프링 배너 출력에 대한 동작은 실제로 크리티컬한 부분은 아니지만 스프링 프레임워크에서 제공해주는 애플리케이션 속성에 따라 동작 여부가 다르다는 건 중요한 부분이라고 생각됩니다.</p><p>spring-dotenv 또는 <a href="https://github.com/spring-projects/spring-boot/issues/24229#issuecomment-783343327" target="_blank" rel="noreferrer">spring.config.import를 통해 .env 파일을 적용하는 예시</a>가 많은데 주의해서 사용할 필요가 있겠네요.</p>`,13)])])}const k=n(a,[["render",r]]);export{d as __pageData,k as default};
